1	//! Divergence analysis: how far a project's code and spec have drifted apart.
2	//! Two read-only agents run at once, one going through the source files and
3	//! one through the spec files, each saying which files on the other side
4	//! influenced or implement them, how strongly, and how far each file diverges.
5	//! Their replies are merged into connections between source and spec files,
6	//! and a divergence score for the whole project.
7	
8	use std::collections::{BTreeMap, HashSet};
9	use std::io::{Read as _, Write as _};
10	use std::path::Path;
11	use std::process::{Child, Command, Stdio};
12	use std::sync::atomic::{AtomicBool, Ordering};
13	use std::sync::{Arc, Mutex};
14	use std::time::Duration;
15	
16	use anyhow::{Context as _, Result, anyhow, bail};
17	use serde::Deserialize;
18	
19	use crate::hidden_anchor;
20	
21	/// The most files of each side analyzed.
22	pub const MAX_FILES: usize = 400;
23	
24	/// How strong a connection has to be to count as strong, or as moderate.
25	pub const STRONG: f32 = 2. / 3.;
26	pub const MODERATE: f32 = 1. / 3.;
27	
28	/// The side of the project a file is on.
29	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
30	pub enum Side {
31	    Source,
32	    Spec,
33	}
34	
35	impl Side {
36	    pub fn other(self) -> Self {
37	        match self {
38	            Side::Source => Side::Spec,
39	            Side::Spec => Side::Source,
40	        }
41	    }
42	
43	    pub fn label(self) -> &'static str {
44	        match self {
45	            Side::Source => "Source",
46	            Side::Spec => "Spec",
47	        }
48	    }
49	}
50	
51	/// An agent's reply: a file it analyzed, and what it found.
52	#[derive(Clone, Debug, Deserialize, PartialEq)]
53	pub struct AgentReply {
54	    pub files: Vec<AgentFile>,
55	}
56	
57	#[derive(Clone, Debug, Deserialize, PartialEq)]
58	pub struct AgentFile {
59	    pub path: String,
60	    pub divergence: f32,
61	    #[serde(default)]
62	    pub summary: String,
63	    #[serde(default)]
64	    pub links: Vec<AgentLink>,
65	}
66	
67	#[derive(Clone, Debug, Deserialize, PartialEq)]
68	pub struct AgentLink {
69	    pub path: String,
70	    pub strength: f32,
71	    #[serde(default)]
72	    pub note: String,
73	}
74	
75	/// A file on one side, as analyzed.
76	#[derive(Clone, Debug, PartialEq)]
77	pub struct FileResult {
78	    pub path: String,
79	    /// From 0 to 1; `None` when the agent left it out.
80	    pub divergence: Option<f32>,
81	    pub summary: String,
82	}
83	
84	/// A source file and a spec file one influenced or implements the other.
85	#[derive(Clone, Debug, PartialEq)]
86	pub struct Connection {
87	    pub source: String,
88	    pub spec: String,
89	    /// From 0 to 1: the average of what the agents said.
90	    pub strength: f32,
91	    pub notes: Vec<String>,
92	}
93	
94	impl Connection {
95	    /// The file at the `side` end of it.
96	    pub fn end(&self, side: Side) -> &str {
97	        match side {
98	            Side::Source => &self.source,
99	            Side::Spec => &self.spec,
100	        }
101	    }
102	}
103	
104	/// What the analysis found.
105	#[derive(Clone, Debug, Default, PartialEq)]
106	pub struct Report {
107	    pub sources: Vec<FileResult>,
108	    pub specs: Vec<FileResult>,
109	    pub connections: Vec<Connection>,
110	}
111	
112	impl Report {
113	    pub fn files(&self, side: Side) -> &[FileResult] {
114	        match side {
115	            Side::Source => &self.sources,
116	            Side::Spec => &self.specs,
117	        }
118	    }
119	
120	    /// The divergence score, as a whole percentage: the average divergence of
121	    /// every file analyzed. `None` when nothing was.
122	    pub fn score(&self) -> Option<u32> {
123	        let analyzed: Vec<f32> = self
124	            .sources
125	            .iter()
126	            .chain(&self.specs)
127	            .filter_map(|file| file.divergence)
128	            .collect();
129	        if analyzed.is_empty() {
130	            return None;
131	        }
132	        let mean = analyzed.iter().sum::<f32>() / analyzed.len() as f32;
133	        Some((mean * 100.).round() as u32)
134	    }
135	
136	    /// The connections of `path`, on `side`, strongest first.
137	    pub fn connections_of(&self, side: Side, path: &str) -> Vec<&Connection> {
138	        let mut connections: Vec<&Connection> = self
139	            .connections
140	            .iter()
141	            .filter(|connection| connection.end(side) == path)
142	            .collect();
143	        connections.sort_by(|a, b| {
144	            b.strength
145	                .total_cmp(&a.strength)
146	                .then_with(|| a.end(side.other()).cmp(b.end(side.other())))
147	        });
148	        connections
149	    }
150	}
151	
152	/// What a divergence score means.
153	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
154	pub enum Verdict {
155	    Aligned,
156	    Drifting,
157	    Diverged,
158	}
159	
160	impl Verdict {
161	    pub fn of(percent: u32) -> Self {
162	        match percent {
163	            0..20 => Verdict::Aligned,
164	            20..50 => Verdict::Drifting,
165	            _ => Verdict::Diverged,
166	        }
167	    }
168	
169	    pub fn label(self) -> &'static str {
170	        match self {
171	            Verdict::Aligned => "Aligned",
172	            Verdict::Drifting => "Drifting",
173	            Verdict::Diverged => "Diverged",
174	        }
175	    }
176	}
177	
178	/// How strong a connection of `strength` is.
179	pub fn strength_label(strength: f32) -> &'static str {
180	    if strength >= STRONG {
181	        "Strong"
182	    } else if strength >= MODERATE {
183	        "Moderate"
184	    } else {
185	        "Weak"
186	    }
187	}
188	
189	/// `path` as the agents and the report write it: relative to the project,
190	/// with `/` between folders and no leading `./`.
191	fn normalize(path: &str) -> String {
192	    path.trim()
193	        .trim_start_matches("./")
194	        .replace('\\', "/")
195	        .trim_end_matches('/')
196	        .to_string()
197	}
198	
199	/// The JSON reply in what an agent printed, which may have a little around it.
200	pub fn parse_reply(text: &str) -> Result<AgentReply> {
201	    let start = text
202	        .find('{')
203	        .ok_or_else(|| anyhow!("the agent's reply has no JSON in it"))?;
204	    let end = text
205	        .rfind('}')
206	        .ok_or_else(|| anyhow!("the agent's reply has no JSON in it"))?;
207	    serde_json::from_str(&text[start..=end]).context("the agent's reply isn't the JSON asked for")
208	}
209	
210	/// Merges what the agents found for `sources` and `specs` into a report.
211	pub fn merge(
212	    sources: &[String],
213	    specs: &[String],
214	    source_reply: Option<&AgentReply>,
215	    spec_reply: Option<&AgentReply>,
216	) -> Report {
217	    let source_set: HashSet<&str> = sources.iter().map(String::as_str).collect();
218	    let spec_set: HashSet<&str> = specs.iter().map(String::as_str).collect();
219	
220	    let results = |paths: &[String], reply: Option<&AgentReply>| -> Vec<FileResult> {
221	        let found: BTreeMap<String, &AgentFile> = reply
222	            .map(|reply| {
223	                reply
224	                    .files
225	                    .iter()
226	                    .map(|file| (normalize(&file.path), file))
227	                    .collect()
228	            })
229	            .unwrap_or_default();
230	        paths
231	            .iter()
232	            .map(|path| match found.get(path) {
233	                Some(file) => FileResult {
234	                    path: path.clone(),
235	                    divergence: Some(file.divergence.clamp(0., 1.)),
236	                    summary: file.summary.trim().to_string(),
237	                },
238	                None => FileResult {
239	                    path: path.clone(),
240	                    divergence: None,
241	                    summary: String::new(),
242	                },
243	            })
244	            .collect()
245	    };
246	
247	    // Each connection, keyed by its source and spec file, with what each
248	    // agent said of it.
249	    let mut links: BTreeMap<(String, String), (Vec<f32>, Vec<String>)> = BTreeMap::new();
250	    let mut note = |source: String, spec: String, link: &AgentLink| {
251	        if !source_set.contains(source.as_str()) || !spec_set.contains(spec.as_str()) {
252	            return;
253	        }
254	        let entry = links.entry((source, spec)).or_default();
255	        entry.0.push(link.strength.clamp(0., 1.));
256	        let text = link.note.trim();
257	        if !text.is_empty() && !entry.1.iter().any(|note| note == text) {
258	            entry.1.push(text.to_string());
259	        }
260	    };
261	    for file in source_reply.map_or(&[][..], |reply| &reply.files) {
262	        for link in &file.links {
263	            note(normalize(&file.path), normalize(&link.path), link);
264	        }
265	    }
266	    for file in spec_reply.map_or(&[][..], |reply| &reply.files) {
267	        for link in &file.links {
268	            note(normalize(&link.path), normalize(&file.path), link);
269	        }
270	    }
271	
272	    Report {
273	        sources: results(sources, source_reply),
274	        specs: results(specs, spec_reply),
275	        connections: links
276	            .into_iter()
277	            .map(|((source, spec), (strengths, notes))| Connection {
278	                source,
279	                spec,
280	                strength: strengths.iter().sum::<f32>() / strengths.len() as f32,
281	                notes,
282	            })
283	            .collect(),
284	    }
285	}
