287	/// A row of a file tree: a folder or a file, and how deep it is.
288	#[derive(Clone, Debug, PartialEq)]
289	pub struct TreeRow {
290	    pub depth: usize,
291	    pub name: String,
292	    /// The file's path, for a file; `None` for a folder.
293	    pub file: Option<String>,
294	}
295	
296	/// `paths` as a tree: a row per folder and file, folders before files, each
297	/// sorted by name.
298	pub fn tree_rows(paths: &[String]) -> Vec<TreeRow> {
299	    #[derive(Default)]
300	    struct Folder {
301	        folders: BTreeMap<String, Folder>,
302	        files: BTreeMap<String, String>,
303	    }
304	    let mut root = Folder::default();
305	    for path in paths {
306	        let parts: Vec<&str> = path.split('/').filter(|part| !part.is_empty()).collect();
307	        let Some((file, folders)) = parts.split_last() else {
308	            continue;
309	        };
310	        let mut folder = &mut root;
311	        for part in folders {
312	            folder = folder.folders.entry(part.to_string()).or_default();
313	        }
314	        folder.files.insert(file.to_string(), path.clone());
315	    }
316	    fn walk(folder: &Folder, depth: usize, rows: &mut Vec<TreeRow>) {
317	        for (name, child) in &folder.folders {
318	            rows.push(TreeRow {
319	                depth,
320	                name: name.clone(),
321	                file: None,
322	            });
323	            walk(child, depth + 1, rows);
324	        }
325	        for (name, path) in &folder.files {
326	            rows.push(TreeRow {
327	                depth,
328	                name: name.clone(),
329	                file: Some(path.clone()),
330	            });
331	        }
332	    }
333	    let mut rows = Vec::new();
334	    walk(&root, 0, &mut rows);
335	    rows
336	}
337	
338	/// The files analyzed on each side, and whether either was cut short.
339	#[derive(Clone, Debug, Default, PartialEq)]
340	pub struct Files {
341	    pub code_root: String,
342	    pub spec_root: String,
343	    pub sources: Vec<String>,
344	    pub specs: Vec<String>,
345	    pub sources_truncated: bool,
346	    pub specs_truncated: bool,
347	}
348	
349	/// The project's source files, under its code location, and spec files, under
350	/// its spec location, relative to the project.
351	pub fn list_files(project_dir: &Path) -> Result<Files> {
352	    let code_root = normalize(&hidden_anchor::config_value(project_dir, "codeRoot")?);
353	    let spec_root = normalize(&hidden_anchor::config_value(project_dir, "root")?);
354	    let (sources, sources_truncated) = walk(project_dir, &code_root, |path| !is_binary(path))?;
355	    let (specs, specs_truncated) = walk(project_dir, &spec_root, |path| {
356	        path.extension().is_some_and(|ext| ext == "pi")
357	    })?;
358	    Ok(Files {
359	        code_root,
360	        spec_root,
361	        sources,
362	        specs,
363	        sources_truncated,
364	        specs_truncated,
365	    })
366	}
367	
368	/// The files under `root` in `project_dir` that Git doesn't ignore and
369	/// `keep` keeps, sorted, at most [`MAX_FILES`] of them.
370	fn walk(
371	    project_dir: &Path,
372	    root: &str,
373	    keep: impl Fn(&Path) -> bool,
374	) -> Result<(Vec<String>, bool)> {
375	    let dir = project_dir.join(root);
376	    if !dir.is_dir() {
377	        bail!("{} isn't a folder", dir.display());
378	    }
379	    let mut files: Vec<String> = ignore::WalkBuilder::new(&dir)
380	        .hidden(false)
381	        .filter_entry(|entry| entry.file_name() != ".git")
382	        .build()
383	        .filter_map(|entry| entry.ok())
384	        .filter(|entry| entry.file_type().is_some_and(|kind| kind.is_file()))
385	        .map(|entry| entry.into_path())
386	        .filter(|path| keep(path))
387	        .filter_map(|path| {
388	            path.strip_prefix(project_dir)
389	                .ok()
390	                .map(|path| normalize(&path.to_string_lossy()))
391	        })
392	        .collect();
393	    files.sort();
394	    let truncated = files.len() > MAX_FILES;
395	    files.truncate(MAX_FILES);
396	    Ok((files, truncated))
397	}
398	
399	/// Whether the file at `path` isn't text.
400	fn is_binary(path: &Path) -> bool {
401	    let mut head = [0u8; 8000];
402	    let Ok(mut file) = std::fs::File::open(path) else {
403	        return true;
404	    };
405	    let read = file.read(&mut head).unwrap_or(0);
406	    head[..read].contains(&0)
407	}
408	
409	/// What an agent is asked to reply with.
410	const REPLY_FORMAT: &str = r#"Reply with nothing but JSON, in this form, with paths relative to the project:
411	{"files": [{"path": "...", "divergence": 0.0, "summary": "...", "links": [{"path": "...", "strength": 0.0, "note": "..."}]}]}"#;
412	
413	/// The prompt for the agent analyzing `side`.
414	pub fn prompt(side: Side, files: &Files) -> String {
415	    let list = |paths: &[String]| paths.join("\n");
416	    let intro = format!(
417	        "We're analyzing how far the code located in {code} and the spec located in {spec} \
418	         have diverged. The spec is written in Piton; its compiled Markdown is in the agent \
419	         directory's reference folder, such as .claude/reference, if that helps. Only read \
420	         files: don't change anything.",
421	        code = files.code_root,
422	        spec = files.spec_root,
423	    );
424	    let task = match side {
425	        Side::Source => {
426	            "Go through every source file listed below. For each one, say which spec files \
427	             drove it or had influence on it, with how strong each influence is, from 0 for \
428	             barely any to 1 for the file being written straight from it, and a short note on \
429	             what it took from it. Say how far the file diverges from the spec, from 0 for doing \
430	             just what the spec describes to 1 for nothing in the spec accounting for it or the \
431	             spec saying otherwise, and sum up in one sentence how it diverges, or that it \
432	             doesn't. Links are to spec files from the spec list."
433	        }
434	        Side::Spec => {
435	            "Go through every spec file listed below. For each one, say which source files \
436	             implement it, with how strongly each does, from 0 for barely at all to 1 for being \
437	             written straight from it, and a short note on what it implements. Say how far the \
438	             code diverges from what the file describes, from 0 for all of it being built as \
439	             described to 1 for none of it being built or the code doing otherwise, and sum up \
440	             in one sentence how it diverges, or that it doesn't. Links are to source files \
441	             from the source list."
442	        }
443	    };
444	    let (analyzed, other) = match side {
445	        Side::Source => ("Source files to analyze", "Spec files"),
446	        Side::Spec => ("Spec files to analyze", "Source files"),
447	    };
448	    let (analyzed_files, other_files) = match side {
449	        Side::Source => (&files.sources, &files.specs),
450	        Side::Spec => (&files.specs, &files.sources),
451	    };
452	    format!(
453	        "{intro}\n\n{task}\n\n{REPLY_FORMAT}\n\n{analyzed}:\n{}\n\n{other}:\n{}\n",
454	        list(analyzed_files),
455	        list(other_files)
456	    )
457	}
