459	/// Stops the agents of an analysis, once set.
460	#[derive(Default)]
461	pub struct Cancel {
462	    cancelled: AtomicBool,
463	}
464	
465	impl Cancel {
466	    pub fn cancel(&self) {
467	        self.cancelled.store(true, Ordering::SeqCst);
468	    }
469	
470	    pub fn is_cancelled(&self) -> bool {
471	        self.cancelled.load(Ordering::SeqCst)
472	    }
473	}
474	
475	/// Runs an agent in a project with a prompt, handing each line it streams to
476	/// the callback as it arrives, and returning its reply.
477	pub type RunAgent = fn(&Path, &str, &Cancel, &dyn Fn(String)) -> Result<String>;
478	
479	/// Runs `piton build` in a project.
480	pub type Build = fn(&Path) -> Result<crate::piton_build::BuildOutcome>;
481	
482	/// The reply in a line of the harness's streamed JSON, when the line is its
483	/// result: whether it is an error, and the result's text.
484	pub fn result_of(line: &str) -> Option<(bool, String)> {
485	    let event: serde_json::Value = serde_json::from_str(line).ok()?;
486	    if event.get("type")?.as_str()? != "result" {
487	        return None;
488	    }
489	    let is_error = event
490	        .get("is_error")
491	        .and_then(serde_json::Value::as_bool)
492	        .unwrap_or(false);
493	    let result = event
494	        .get("result")
495	        .and_then(serde_json::Value::as_str)
496	        .unwrap_or_default()
497	        .to_string();
498	    Some((is_error, result))
499	}
500	
501	/// Runs the harness once in `project_dir` with `prompt`, only able to read,
502	/// glob, and search files, keeping no session. Each line of JSON it streams
503	/// goes to `on_line` as it arrives; its reply is the result it finishes with.
504	/// Stops it if `cancel` is set while it runs.
505	pub fn run_agent(
506	    project_dir: &Path,
507	    prompt: &str,
508	    cancel: &Cancel,
509	    on_line: &dyn Fn(String),
510	) -> Result<String> {
511	    let mut child = Command::new("claude")
512	        .args([
513	            "-p",
514	            "--tools",
515	            "Read,Glob,Grep",
516	            "--no-session-persistence",
517	            "--output-format",
518	            "stream-json",
519	            "--verbose",
520	        ])
521	        .current_dir(project_dir)
522	        .stdin(Stdio::piped())
523	        .stdout(Stdio::piped())
524	        .stderr(Stdio::piped())
525	        .spawn()
526	        .context("could not run claude")?;
527	    let mut stdin = child
528	        .stdin
529	        .take()
530	        .ok_or_else(|| anyhow!("claude has no stdin"))?;
531	    let prompt = prompt.to_string();
532	    let writer = std::thread::spawn(move || stdin.write_all(prompt.as_bytes()));
533	    // Lines come through a channel, so they reach `on_line` on this thread.
534	    let (lines, streamed) = std::sync::mpsc::channel::<String>();
535	    let stdout = child.stdout.take();
536	    let reader = std::thread::spawn(move || {
537	        if let Some(stdout) = stdout {
538	            for line in std::io::BufRead::lines(std::io::BufReader::new(stdout)) {
539	                let Ok(line) = line else { break };
540	                if lines.send(line).is_err() {
541	                    break;
542	                }
543	            }
544	        }
545	    });
546	    let stderr = child.stderr.take();
547	    let stderr = std::thread::spawn(move || {
548	        let mut text = String::new();
549	        if let Some(mut stderr) = stderr {
550	            stderr.read_to_string(&mut text).ok();
551	        }
552	        text
553	    });
554	    let child = Arc::new(Mutex::new(child));
555	    let mut result = None;
556	    let mut take = |line: String| {
557	        if let Some(found) = result_of(&line) {
558	            result = Some(found);
559	        }
560	        if !line.trim().is_empty() {
561	            on_line(line);
562	        }
563	    };
564	    let status = loop {
565	        while let Ok(line) = streamed.try_recv() {
566	            take(line);
567	        }
568	        if cancel.is_cancelled() {
569	            kill(&child);
570	            bail!("stopped");
571	        }
572	        if let Some(status) = child.lock().unwrap().try_wait()? {
573	            break status;
574	        }
575	        std::thread::sleep(Duration::from_millis(50));
576	    };
577	    writer.join().ok();
578	    reader.join().ok();
579	    while let Ok(line) = streamed.try_recv() {
580	        take(line);
581	    }
582	    let stderr = stderr.join().unwrap_or_default();
583	    match result {
584	        Some((false, reply)) => Ok(reply),
585	        Some((true, reply)) => bail!("{}", reply.trim()),
586	        None if !status.success() => bail!("{}", stderr.trim()),
587	        None => bail!("the agent finished without a result"),
588	    }
589	}
590	
591	fn kill(child: &Arc<Mutex<Child>>) {
592	    let mut child = child.lock().unwrap();
593	    child.kill().ok();
594	    child.wait().ok();
595	}
