597	#[cfg(test)]
598	mod tests {
599	    use std::path::Path;
600	
601	    use super::{
602	        AgentReply, Side, Verdict, list_files, merge, normalize, parse_reply, strength_label,
603	        tree_rows,
604	    };
605	
606	    fn reply(json: &str) -> AgentReply {
607	        parse_reply(json).unwrap()
608	    }
609	
610	    /// A reply is read even with text around its JSON, and one that isn't the
611	    /// JSON asked for says so.
612	    #[test]
613	    fn replies_are_parsed() {
614	        let parsed = reply(
615	            "Here you go:\n{\"files\": [{\"path\": \"./src/a.rs\", \"divergence\": 0.5, \
616	             \"links\": [{\"path\": \"spec/a.pi\", \"strength\": 0.9}]}]}\nDone.",
617	        );
618	        assert_eq!(parsed.files[0].links[0].strength, 0.9);
619	        assert!(parse_reply("no json").is_err());
620	        assert!(parse_reply("{\"nope\": 1}").is_err());
621	        assert_eq!(normalize("./src\\a.rs"), "src/a.rs");
622	    }
623	
624	    /// Connections from both sides are joined by their files and averaged;
625	    /// ones to files outside either list are dropped; files an agent left out
626	    /// aren't analyzed and don't count towards the score.
627	    #[test]
628	    fn replies_merge_into_connections_and_a_score() {
629	        let sources = vec!["src/a.rs".to_string(), "src/b.rs".to_string()];
630	        let specs = vec!["spec/a.pi".to_string(), "spec/b.pi".to_string()];
631	        let source_reply = reply(
632	            r#"{"files": [
633	                {"path": "src/a.rs", "divergence": 0.2, "summary": "Mostly as described.",
634	                 "links": [{"path": "spec/a.pi", "strength": 1.0, "note": "the layout"},
635	                           {"path": "spec/nowhere.pi", "strength": 0.5}]}
636	            ]}"#,
637	        );
638	        let spec_reply = reply(
639	            r#"{"files": [
640	                {"path": "spec/a.pi", "divergence": 0.4,
641	                 "links": [{"path": "src/a.rs", "strength": 0.6, "note": "the layout"},
642	                           {"path": "src/b.rs", "strength": 0.2, "note": "a little"}]},
643	                {"path": "spec/b.pi", "divergence": 1.5}
644	            ]}"#,
645	        );
646	        let report = merge(&sources, &specs, Some(&source_reply), Some(&spec_reply));
647	
648	        assert_eq!(report.sources[0].divergence, Some(0.2));
649	        assert_eq!(report.sources[1].divergence, None, "b.rs was analyzed");
650	        assert_eq!(
651	            report.specs[1].divergence,
652	            Some(1.),
653	            "divergence isn't clamped"
654	        );
655	        assert_eq!(report.connections.len(), 2);
656	        let a = &report.connections_of(Side::Source, "src/a.rs")[0];
657	        assert_eq!((a.spec.as_str(), a.strength), ("spec/a.pi", 0.8));
658	        assert_eq!(a.notes, ["the layout"]);
659	        let of_spec = report.connections_of(Side::Spec, "spec/a.pi");
660	        assert_eq!(
661	            of_spec
662	                .iter()
663	                .map(|c| c.source.as_str())
664	                .collect::<Vec<_>>(),
665	            ["src/a.rs", "src/b.rs"],
666	            "strongest first"
667	        );
668	        // (0.2 + 0.4 + 1.0) / 3
669	        assert_eq!(report.score(), Some(53));
670	        assert_eq!(merge(&sources, &specs, None, None).score(), None);
671	    }
672	
673	    #[test]
674	    fn scores_and_strengths_are_named() {
675	        assert_eq!(Verdict::of(0), Verdict::Aligned);
676	        assert_eq!(Verdict::of(19), Verdict::Aligned);
677	        assert_eq!(Verdict::of(20), Verdict::Drifting);
678	        assert_eq!(Verdict::of(50), Verdict::Diverged);
679	        assert_eq!(strength_label(0.9), "Strong");
680	        assert_eq!(strength_label(0.4), "Moderate");
681	        assert_eq!(strength_label(0.1), "Weak");
682	    }
683	
684	    /// The reply is the result the stream ends with.
685	    #[test]
686	    fn results_are_found_in_the_stream() {
687	        use super::result_of;
688	        assert_eq!(result_of(r#"{"type":"assistant","message":{}}"#), None);
689	        assert_eq!(result_of("not json"), None);
690	        assert_eq!(
691	            result_of(r#"{"type":"result","is_error":false,"result":"{\"files\": []}"}"#),
692	            Some((false, r#"{"files": []}"#.to_string()))
693	        );
694	        assert_eq!(
695	            result_of(r#"{"type":"result","is_error":true,"result":"overloaded"}"#),
696	            Some((true, "overloaded".to_string()))
697	        );
698	    }
699	
700	    /// Folders come before files, each sorted, indented by depth.
701	    #[test]
702	    fn paths_become_a_tree() {
703	        let paths = ["src/main.rs", "src/ui/b.rs", "src/ui/a.rs", "build.rs"]
704	            .map(String::from)
705	            .to_vec();
706	        let rows: Vec<(usize, String, bool)> = tree_rows(&paths)
707	            .into_iter()
708	            .map(|row| (row.depth, row.name, row.file.is_some()))
709	            .collect();
710	        let rows: Vec<(usize, &str, bool)> = rows
711	            .iter()
712	            .map(|(depth, name, file)| (*depth, name.as_str(), *file))
713	            .collect();
714	        assert_eq!(
715	            rows,
716	            [
717	                (0, "src", false),
718	                (1, "ui", false),
719	                (2, "a.rs", true),
720	                (2, "b.rs", true),
721	                (1, "main.rs", true),
722	                (0, "build.rs", true),
723	            ]
724	        );
725	    }
726	
727	    /// This project's own files: text source files under src, and .pi files
728	    /// under spec.
729	    #[test]
730	    fn lists_this_projects_files() {
731	        let files = list_files(Path::new(env!("CARGO_MANIFEST_DIR"))).unwrap();
732	        assert_eq!(
733	            (files.code_root.as_str(), files.spec_root.as_str()),
734	            ("src", "spec")
735	        );
736	        assert!(files.sources.contains(&"src/divergence.rs".to_string()));
737	        assert!(files.sources.iter().all(|path| path.starts_with("src/")));
738	        assert!(
739	            files
740	                .specs
741	                .contains(&"spec/scope/divergence/index.pi".to_string())
742	        );
743	        assert!(files.specs.iter().all(|path| path.ends_with(".pi")));
744	    }
745	}
