1	//! The divergence panel: runs an analysis of how far the open project's code
2	//! and spec have diverged, showing its steps as they run, then the score and
3	//! the source and spec trees, where a selected file shows its connections to
4	//! files on the other side, strongest first.
5	
6	use std::collections::VecDeque;
7	use std::path::PathBuf;
8	use std::sync::Arc;
9	
10	use futures::StreamExt as _;
11	
12	use anyhow::Result;
13	use gpui_kit::assets::IconName;
14	use gpui_kit::component::button::{Button, ButtonVariants as _};
15	use gpui_kit::component::spinner::Spinner;
16	use gpui_kit::component::{
17	    ActiveTheme as _, Disableable as _, Icon, Selectable as _, Sizable as _, StyledExt as _,
18	    h_flex, v_flex,
19	};
20	use gpui_kit::prelude::FluentBuilder as _;
21	use gpui_kit::*;
22	
23	use crate::divergence::{
24	    self, AgentReply, Build, Cancel, Files, Report, RunAgent, Side, Verdict, strength_label,
25	    tree_rows,
26	};
27	use crate::scrollbar;
28	
29	actions!(suspense, [AnalyzeDivergence]);
30	
31	/// Emitted when the panel is closed.
32	pub struct CloseDivergence;
33	
34	/// Emitted to hide the panel while the analysis carries on.
35	pub struct MinimizeDivergence;
36	
37	/// How a step of the analysis is going.
38	#[derive(Clone, Debug, PartialEq)]
39	pub enum StepState {
40	    Pending,
41	    Running,
42	    Done,
43	    Failed(SharedString),
44	}
45	
46	/// The steps of an analysis, in the order they run.
47	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
48	pub enum Step {
49	    Build,
50	    Code,
51	    Spec,
52	}
53	
54	/// How many of an agent's latest streamed lines show while it runs, and how
55	/// much of each is kept.
56	const STREAM_LINES: usize = 3;
57	const STREAM_LINE_CHARS: usize = 400;
58	
59	impl Step {
60	    const ALL: [Step; 3] = [Step::Build, Step::Code, Step::Spec];
61	
62	    fn label(self) -> &'static str {
63	        match self {
64	            Step::Build => "Building the spec",
65	            Step::Code => "Analyzing the code",
66	            Step::Spec => "Analyzing the spec",
67	        }
68	    }
69	}
70	
71	pub struct DivergenceView {
72	    project_dir: PathBuf,
73	    build: Build,
74	    agent: RunAgent,
75	    steps: [StepState; 3],
76	    /// Whether the build failed, so the compiled spec may be out of date.
77	    build_failed: bool,
78	    /// Why the files couldn't be listed, if they couldn't.
79	    error: Option<SharedString>,
80	    files: Option<Files>,
81	    /// The latest lines each agent has streamed, newest last, by step.
82	    streams: [VecDeque<String>; 3],
83	    report: Option<Report>,
84	    side: Side,
85	    selected: Option<String>,
86	    tree_scroll: ScrollHandle,
87	    details_scroll: ScrollHandle,
88	    focus_handle: FocusHandle,
89	    /// Stops the running analysis's agents.
90	    cancel: Arc<Cancel>,
91	    _run: Task<()>,
92	}
93	
94	impl EventEmitter<CloseDivergence> for DivergenceView {}
95	impl EventEmitter<MinimizeDivergence> for DivergenceView {}
96	
97	impl Focusable for DivergenceView {
98	    fn focus_handle(&self, _: &App) -> FocusHandle {
99	        self.focus_handle.clone()
100	    }
101	}
102	
103	impl Drop for DivergenceView {
104	    fn drop(&mut self) {
105	        // Closed while it runs, the agents stop.
106	        self.cancel.cancel();
107	    }
108	}
109	
110	impl DivergenceView {
111	    /// A panel analyzing the project in `project_dir`, starting straight away.
112	    pub fn new(project_dir: PathBuf, cx: &mut Context<Self>) -> Self {
113	        Self::with_runners(
114	            project_dir,
115	            crate::piton_build::build,
116	            divergence::run_agent,
117	            cx,
118	        )
119	    }
120	
121	    /// As [`Self::new`], building and running agents with `build` and `agent`.
122	    pub fn with_runners(
123	        project_dir: PathBuf,
124	        build: Build,
125	        agent: RunAgent,
126	        cx: &mut Context<Self>,
127	    ) -> Self {
128	        let mut this = Self {
129	            project_dir,
130	            build,
131	            agent,
132	            steps: Step::ALL.map(|_| StepState::Pending),
133	            build_failed: false,
134	            error: None,
135	            files: None,
136	            streams: Default::default(),
137	            report: None,
138	            side: Side::Source,
139	            selected: None,
140	            tree_scroll: ScrollHandle::new(),
141	            details_scroll: ScrollHandle::new(),
142	            focus_handle: cx.focus_handle(),
143	            cancel: Arc::default(),
144	            _run: Task::ready(()),
145	        };
146	        this.analyze(cx);
147	        this
148	    }
149	
150	    #[cfg(test)]
151	    pub fn report(&self) -> Option<&Report> {
152	        self.report.as_ref()
153	    }
154	
155	    #[cfg(test)]
156	    pub fn side(&self) -> Side {
157	        self.side
158	    }
159	
160	    #[cfg(test)]
161	    pub fn selected(&self) -> Option<&str> {
162	        self.selected.as_deref()
163	    }
164	
165	    #[cfg(test)]
166	    pub fn step(&self, step: Step) -> &StepState {
167	        &self.steps[step as usize]
168	    }
169	
170	    /// Holds the analysis as if its agents were still running, for tests
171	    /// elsewhere; `false` lets it finish.
172	    #[cfg(test)]
173	    pub fn hold_running_for_test(&mut self, running: bool, cx: &mut Context<Self>) {
174	        let state = if running {
175	            StepState::Running
176	        } else {
177	            StepState::Done
178	        };
179	        self.steps[Step::Code as usize] = state.clone();
180	        self.steps[Step::Spec as usize] = state;
181	        cx.notify();
182	    }
183	
184	    /// Whether the analysis is still running.
185	    pub fn is_running(&self) -> bool {
186	        self.running()
187	    }
188	
189	    #[cfg(test)]
190	    pub fn stream(&self, step: Step) -> Vec<String> {
191	        self.streams[step as usize].iter().cloned().collect()
192	    }
193	
194	    /// Keeps `line` as the latest `step`'s agent streamed.
195	    fn stream_line(&mut self, step: Step, mut line: String, cx: &mut Context<Self>) {
196	        if let Some((end, _)) = line.char_indices().nth(STREAM_LINE_CHARS) {
197	            line.truncate(end);
198	        }
199	        let stream = &mut self.streams[step as usize];
200	        if stream.len() == STREAM_LINES {
201	            stream.pop_front();
202	        }
203	        stream.push_back(line);
204	        cx.notify();
205	    }
206	
207	    fn running(&self) -> bool {
208	        self.steps
209	            .iter()
210	            .any(|state| matches!(state, StepState::Running | StepState::Pending))
211	            && self.error.is_none()
212	    }
213	
214	    fn set_step(&mut self, step: Step, state: StepState, cx: &mut Context<Self>) {
215	        self.steps[step as usize] = state;
216	        cx.notify();
217	    }
218	
219	    /// Starts a fresh analysis: builds the spec, then runs both agents at
220	    /// once, and merges what they found.
221	    pub fn analyze(&mut self, cx: &mut Context<Self>) {
222	        self.cancel.cancel();
223	        self.cancel = Arc::default();
224	        self.steps = Step::ALL.map(|_| StepState::Pending);
225	        self.build_failed = false;
226	        self.error = None;
227	        self.files = None;
228	        self.streams = Default::default();
229	        self.report = None;
230	        self.selected = None;
231	        self.side = Side::Source;
232	        cx.notify();
233	
234	        let (project_dir, build, agent, cancel) = (
235	            self.project_dir.clone(),
236	            self.build,
237	            self.agent,
238	            self.cancel.clone(),
239	        );
240	        self._run = cx.spawn(async move |this, cx| {
241	            let listed = cx
242	                .background_spawn({
243	                    let project_dir = project_dir.clone();
244	                    async move { divergence::list_files(&project_dir) }
245	                })
246	                .await;
247	            let files = match listed {
248	                Ok(files) => files,
249	                Err(err) => {
250	                    this.update(cx, |this, cx| {
251	                        this.error = Some(format!("{err:#}").into());
252	                        cx.notify();
253	                    })
254	                    .ok();
255	                    return;
256	                }
257	            };
258	
259	            this.update(cx, |this, cx| {
260	                this.files = Some(files.clone());
261	                this.set_step(Step::Build, StepState::Running, cx)
262	            })
263	            .ok();
264	            let built = cx
265	                .background_spawn({
266	                    let project_dir = project_dir.clone();
267	                    async move { build(&project_dir) }
268	                })
269	                .await;
270	            let build_failed = !matches!(built, Ok(ref outcome) if outcome.success);
271	            let updated = this.update(cx, |this, cx| {
272	                this.build_failed = build_failed;
273	                this.set_step(Step::Build, StepState::Done, cx);
274	                this.set_step(Step::Code, StepState::Running, cx);
275	                this.set_step(Step::Spec, StepState::Running, cx);
276	            });
277	            if updated.is_err() {
278	                return;
279	            }
280	
281	            // Each agent streams its lines back as it runs.
282	            let (lines, streamed) = futures::channel::mpsc::unbounded::<(Step, String)>();
283	            let run = |side: Side, step: Step| {
284	                let (project_dir, cancel, prompt, lines) = (
285	                    project_dir.clone(),
286	                    cancel.clone(),
287	                    divergence::prompt(side, &files),
288	                    lines.clone(),
289	                );
290	                cx.background_spawn(async move {
291	                    let reply = agent(&project_dir, &prompt, &cancel, &|line| {
292	                        lines.unbounded_send((step, line)).ok();
293	                    })?;
294	                    divergence::parse_reply(&reply)
295	                })
296	            };
297	            let (code, spec) = (run(Side::Source, Step::Code), run(Side::Spec, Step::Spec));
298	            // Once both agents are over, their senders are gone and the
299	            // stream ends.
300	            drop(lines);
301	            let mut streamed = streamed;
302	            while let Some((step, line)) = streamed.next().await {
303	                if this
304	                    .update(cx, |this, cx| this.stream_line(step, line, cx))
305	                    .is_err()
306	                {
307	                    return;
308	                }
309	            }
310	            let (code, spec): (Result<AgentReply>, Result<AgentReply>) = futures::join!(code, spec);
311	
312	            this.update(cx, |this, cx| {
313	                let state = |result: &Result<AgentReply>| match result {
314	                    Ok(_) => StepState::Done,
315	                    Err(err) => StepState::Failed(format!("{err:#}").into()),
316	                };
317	                this.steps[Step::Code as usize] = state(&code);
318	                this.steps[Step::Spec as usize] = state(&spec);
319	                if code.is_ok() || spec.is_ok() {
320	                    let report = divergence::merge(
321	                        &files.sources,
322	                        &files.specs,
323	                        code.as_ref().ok(),
324	                        spec.as_ref().ok(),
325	                    );
326	                    // The source file that diverges most is selected.
327	                    this.selected = report
328	                        .sources
329	                        .iter()
330	                        .filter_map(|file| Some((file.divergence?, &file.path)))
331	                        .max_by(|a, b| a.0.total_cmp(&b.0))
332	                        .map(|(_, path)| path.clone());
333	                    this.report = Some(report);
334	                }
335	                cx.notify();
336	            })
337	            .ok();
338	        });
339	    }
340	
341	    fn close(&mut self, cx: &mut Context<Self>) {
342	        self.cancel.cancel();
343	        cx.emit(CloseDivergence);
344	    }
345	
346	    pub fn set_side(&mut self, side: Side, cx: &mut Context<Self>) {
347	        if self.side != side {
348	            self.side = side;
349	            self.selected = None;
350	            self.tree_scroll.set_offset(point(px(0.), px(0.)));
351	            cx.notify();
352	        }
353	    }
354	
355	    pub fn select(&mut self, path: String, cx: &mut Context<Self>) {
356	        self.selected = Some(path);
357	        self.details_scroll.set_offset(point(px(0.), px(0.)));
358	        cx.notify();
359	    }
360	
361	    /// Follows a connection to `path` on the other side: that tree, with the
362	    /// file selected and scrolled into view.
363	    pub fn follow(&mut self, path: String, cx: &mut Context<Self>) {
364	        self.side = self.side.other();
365	        let row = self
366	            .files
367	            .as_ref()
368	            .map(|_| self.tree_paths())
369	            .and_then(|paths| {
370	                tree_rows(&paths)
371	                    .iter()
372	                    .position(|row| row.file.as_deref() == Some(path.as_str()))
373	            });
374	        self.select(path, cx);
375	        if let Some(row) = row {
376	            self.tree_scroll.scroll_to_item(row);
377	        }
378	    }
379	
380	    fn tree_paths(&self) -> Vec<String> {
381	        self.report
382	            .as_ref()
383	            .map(|report| {
384	                report
385	                    .files(self.side)
386	                    .iter()
387	                    .map(|file| file.path.clone())
388	                    .collect()
389	            })
390	            .unwrap_or_default()
391	    }
392	
393	    fn verdict_color(percent: u32, cx: &App) -> Hsla {
394	        let theme = cx.theme();
395	        match Verdict::of(percent) {
396	            Verdict::Aligned => theme.success,
397	            Verdict::Drifting => theme.warning,
398	            Verdict::Diverged => theme.danger,
399	        }
400	    }
401	
402	    fn render_header(&self, cx: &mut Context<Self>) -> impl IntoElement {
403	        let theme = cx.theme();
404	        let score = self.report.as_ref().and_then(Report::score);
405	        h_flex()
406	            .flex_none()
407	            .gap_3()
408	            .pl_4()
409	            .pr_1()
410	            .py_2()
411	            .border_b_1()
412	            .border_color(theme.border)
413	            .child(
414	                Icon::new(IconName::GitCompareArrows)
415	                    .small()
416	                    .text_color(theme.muted_foreground),
417	            )
418	            .child(div().font_semibold().child("Divergence"))
419	            .when_some(score, |header, score| {
420	                let color = Self::verdict_color(score, cx);
421	                header.child(gpui_kit::TestSupportExt::test_support(
422	                    h_flex()
423	                        .id("divergence-score")
424	                        .gap_2()
425	                        .items_baseline()
426	                        .child(
427	                            div()
428	                                .text_2xl()
429	                                .font_bold()
430	                                .text_color(color)
431	                                .child(format!("{score}%")),
432	                        )
433	                        .child(
434	                            div()
435	                                .text_sm()
436	                                .text_color(color)
437	                                .child(Verdict::of(score).label()),
438	                        ),
439	                ))
440	            })
441	            .child(div().flex_1())
442	            .child(
443	                Button::new("divergence-analyze-again")
444	                    .ghost()
445	                    .small()
446	                    .icon(IconName::RefreshCw)
447	                    .label("Analyze again")
448	                    .disabled(self.running())
449	                    .on_click(cx.listener(|this, _, _, cx| this.analyze(cx))),
450	            )
451	            .child(
452	                Button::new("divergence-minimize")
453	                    .ghost()
454	                    .small()
455	                    .icon(IconName::Minus)
456	                    .tooltip("Minimize; the analysis keeps running")
457	                    .on_click(cx.listener(|_, _, _, cx| cx.emit(MinimizeDivergence))),
458	            )
459	            .child(
460	                Button::new("divergence-close")
461	                    .ghost()
462	                    .small()
463	                    .icon(IconName::X)
464	                    .tooltip("Close, stopping any analysis still running")
465	                    .on_click(cx.listener(|this, _, _, cx| this.close(cx))),
466	            )
467	    }
468	
469	    fn render_steps(&self, cx: &mut Context<Self>) -> impl IntoElement {
470	        let theme = cx.theme();
471	        v_flex()
472	            .id("divergence-steps")
473	            .gap_2()
474	            .p_6()
475	            .children(self.error.clone().map(|error| {
476	                div()
477	                    .text_color(theme.danger)
478	                    .child(format!("Couldn't analyze the project: {error}"))
479	            }))
480	            .children(Step::ALL.into_iter().map(|step| {
481	                let state = &self.steps[step as usize];
482	                let icon: AnyElement = match state {
483	                    StepState::Pending => div().size_4().into_any_element(),
484	                    StepState::Running => Spinner::new().small().into_any_element(),
485	                    StepState::Done => Icon::new(IconName::Check)
486	                        .small()
487	                        .text_color(theme.success)
488	                        .into_any_element(),
489	                    StepState::Failed(_) => Icon::new(IconName::X)
490	                        .small()
491	                        .text_color(theme.danger)
492	                        .into_any_element(),
493	                };
494	                // While its agent runs, the latest lines it streamed.
495	                let stream = (*state == StepState::Running
496	                    && matches!(step, Step::Code | Step::Spec))
497	                .then(|| {
498	                    let lines = &self.streams[step as usize];
499	                    v_flex()
500	                        .id(("divergence-stream", step as usize))
501	                        .pl_6()
502	                        .w_full()
503	                        .min_w_0()
504	                        .text_sm()
505	                        .font_family(theme.mono_font_family.clone())
506	                        .text_color(theme.muted_foreground)
507	                        .children((0..STREAM_LINES).map(|ix| {
508	                            let line: AnyElement = match lines.get(ix) {
509	                                Some(line) => crate::prompt_mode::highlighted_json(line, cx)
510	                                    .into_any_element(),
511	                                None if ix == 0 => "Waiting for the harness…".into_any_element(),
512	                                // A no-break space keeps an empty line a line tall.
513	                                None => "\u{a0}".into_any_element(),
514	                            };
515	                            div().w_full().min_w_0().truncate().child(line)
516	                        }))
517	                });
518	                v_flex()
519	                    .gap_0p5()
520	                    .child(
521	                        h_flex().gap_2().child(icon).child(
522	                            div()
523	                                .when(*state == StepState::Pending, |label| {
524	                                    label.text_color(theme.muted_foreground)
525	                                })
526	                                .child(step.label()),
527	                        ),
528	                    )
529	                    .when_some(
530	                        match state {
531	                            StepState::Failed(why) => Some(why.clone()),
532	                            _ => None,
533	                        },
534	                        |row, why| {
535	                            row.child(div().pl_6().text_sm().text_color(theme.danger).child(why))
536	                        },
537	                    )
538	                    .children(stream.map(gpui_kit::TestSupportExt::test_support))
539	            }))
540	    }
541	
542	    /// Notes about the results: a failed build, a side cut short, or an agent
543	    /// that failed.
544	    fn notes(&self) -> Vec<String> {
545	        let mut notes = Vec::new();
546	        if self.build_failed {
547	            notes.push("piton build failed, so the compiled spec may be out of date.".into());
548	        }
549	        if let Some(files) = &self.files {
550	            if files.sources_truncated {
551	                notes.push(format!(
552	                    "Only the first {} source files were analyzed.",
553	                    divergence::MAX_FILES
554	                ));
555	            }
556	            if files.specs_truncated {
557	                notes.push(format!(
558	                    "Only the first {} spec files were analyzed.",
559	                    divergence::MAX_FILES
560	                ));
561	            }
562	        }
563	        for step in [Step::Code, Step::Spec] {
564	            if let StepState::Failed(why) = &self.steps[step as usize] {
565	                notes.push(format!("{} failed: {why}", step.label()));
566	            }
567	        }
568	        notes
569	    }
570	
571	    fn render_tree(&self, report: &Report, cx: &mut Context<Self>) -> AnyElement {
572	        let theme = cx.theme();
573	        let files = report.files(self.side);
574	        let paths: Vec<String> = files.iter().map(|file| file.path.clone()).collect();
575	        let rows = tree_rows(&paths).into_iter().enumerate().map(|(ix, row)| {
576	            let indent = px(12. + 14. * row.depth as f32);
577	            let Some(path) = row.file else {
578	                return h_flex()
579	                    .id(("divergence-folder", ix))
580	                    .gap_1p5()
581	                    .pl(indent)
582	                    .py_0p5()
583	                    .text_color(theme.muted_foreground)
584	                    .child(Icon::new(IconName::FolderOpen).xsmall())
585	                    .child(row.name)
586	                    .into_any_element();
587	            };
588	            let divergence = files
589	                .iter()
590	                .find(|file| file.path == path)
591	                .and_then(|file| file.divergence);
592	            let selected = self.selected.as_deref() == Some(path.as_str());
593	            let meter = match divergence {
594	                Some(value) => {
595	                    let percent = (value * 100.).round() as u32;
596	                    let color = Self::verdict_color(percent, cx);
597	                    h_flex()
598	                        .flex_none()
599	                        .gap_2()
600	                        .child(
601	                            div()
602	                                .w(px(48.))
603	                                .h(px(4.))
604	                                .rounded_full()
605	                                .bg(theme.muted)
606	                                .child(div().h_full().rounded_full().bg(color).w(relative(value))),
607	                        )
608	                        .child(
609	                            div()
610	                                .w(px(36.))
611	                                .text_right()
612	                                .text_xs()
613	                                .text_color(theme.muted_foreground)
614	                                .child(format!("{percent}%")),
615	                        )
616	                        .into_any_element()
617	                }
618	                None => div()
619	                    .flex_none()
620	                    .text_xs()
621	                    .text_color(theme.muted_foreground)
622	                    .child("Not analyzed")
623	                    .into_any_element(),
624	            };
625	            let target = path.clone();
626	            let row = h_flex()
627	                .id(("divergence-file", ix))
628	                .gap_2()
629	                .pl(indent)
630	                .pr_2()
631	                .py_0p5()
632	                .cursor_pointer()
633	                .when(selected, |row| row.bg(theme.list_active))
634	                .when(!selected, |row| row.hover(|row| row.bg(theme.list_hover)))
635	                .on_click(cx.listener(move |this, _, _, cx| this.select(target.clone(), cx)))
636	                .child(
637	                    Icon::new(IconName::File)
638	                        .xsmall()
639	                        .text_color(theme.muted_foreground),
640	                )
641	                .child(div().flex_1().min_w_0().truncate().child(row.name))
642	                .child(meter);
643	            // Lets UI tests find the row; inert in normal builds.
644	            gpui_kit::TestSupportExt::test_support(row).into_any_element()
645	        });
646	        let list = v_flex()
647	            .id("divergence-tree")
648	            .size_full()
649	            .overflow_y_scroll()
650	            .track_scroll(&self.tree_scroll)
651	            .py_1()
652	            .children(rows);
653	        scrollbar::with_scrollbar("divergence-tree", &self.tree_scroll, list, true, None, cx)
654	    }
655	
656	    fn render_details(&self, report: &Report, cx: &mut Context<Self>) -> AnyElement {
657	        let theme = cx.theme();
658	        let Some(path) = &self.selected else {
659	            return div()
660	                .p_6()
661	                .text_color(theme.muted_foreground)
662	                .child("Select a file to see what it's connected to.")
663	                .into_any_element();
664	        };
665	        let file = report
666	            .files(self.side)
667	            .iter()
668	            .find(|file| &file.path == path);
669	        let divergence = file.and_then(|file| file.divergence);
670	        let other = self.side.other();
671	        let connections = report.connections_of(self.side, path);
672	        let rows = connections.iter().enumerate().map(|(ix, connection)| {
673	            let target = connection.end(other).to_string();
674	            let strength = connection.strength;
675	            let row = v_flex()
676	                .id(("divergence-connection", ix))
677	                .gap_1()
678	                .px_3()
679	                .py_2()
680	                .rounded(theme.radius)
681	                .border_1()
682	                .border_color(theme.border)
683	                .cursor_pointer()
684	                .hover(|row| row.bg(theme.list_hover))
685	                .on_click(cx.listener(move |this, _, _, cx| this.follow(target.clone(), cx)))
686	                .child(
687	                    h_flex()
688	                        .gap_2()
689	                        .child(
690	                            div()
691	                                .flex_1()
692	                                .min_w_0()
693	                                .truncate()
694	                                .font_family(theme.mono_font_family.clone())
695	                                .child(connection.end(other).to_string()),
696	                        )
697	                        .child(
698	                            div()
699	                                .flex_none()
700	                                .text_sm()
701	                                .text_color(theme.muted_foreground)
702	                                .child(format!(
703	                                    "{} · {}%",
704	                                    strength_label(strength),
705	                                    (strength * 100.).round() as u32
706	                                )),
707	                        ),
708	                )
709	                .child(
710	                    div()
711	                        .w_full()
712	                        .h(px(6.))
713	                        .rounded_full()
714	                        .bg(theme.muted)
715	                        .child(
716	                            div()
717	                                .h_full()
718	                                .rounded_full()
719	                                .bg(theme.primary.opacity(0.35 + 0.65 * strength))
720	                                .w(relative(strength)),
721	                        ),
722	                )
723	                .children((!connection.notes.is_empty()).then(|| {
724	                    div()
725	                        .text_sm()
726	                        .text_color(theme.muted_foreground)
727	                        .child(connection.notes.join(" · "))
728	                }));
729	            // Lets UI tests find the connection; inert in normal builds.
730	            gpui_kit::TestSupportExt::test_support(row)
731	        });
732	        let body = v_flex()
733	            .id("divergence-details")
734	            .size_full()
735	            .overflow_y_scroll()
736	            .track_scroll(&self.details_scroll)
737	            .gap_3()
738	            .p_4()
739	            .child(
740	                div()
741	                    .font_semibold()
742	                    .font_family(theme.mono_font_family.clone())
743	                    .child(path.clone()),
744	            )
745	            .child(
746	                div()
747	                    .text_sm()
748	                    .text_color(theme.muted_foreground)
749	                    .child(match divergence {
750	                        Some(value) => format!("Diverges {}%", (value * 100.).round() as u32),
751	                        None => "Not analyzed".to_string(),
752	                    }),
753	            )
754	            .children(
755	                file.map(|file| file.summary.clone())
756	                    .filter(|summary| !summary.is_empty())
757	                    .map(|summary| div().child(summary)),
758	            )
759	            .child(div().pt_2().font_medium().child(match connections.len() {
760	                0 => format!("No connected {} files", other.label().to_lowercase()),
761	                1 => format!("1 connected {} file", other.label().to_lowercase()),
762	                n => format!("{n} connected {} files", other.label().to_lowercase()),
763	            }))
764	            .children(rows);
765	        scrollbar::with_scrollbar(
766	            "divergence-details",
767	            &self.details_scroll,
768	            body,
769	            true,
770	            None,
771	            cx,
772	        )
773	    }
