882	                           {"path": "spec/ui/components/scrollbar/index.pi", "strength": 0.5}]}
883	            ]}"#
884	        } else {
885	            r#"{"files": [
886	                {"path": "spec/ui/components/scrollbar/index.pi", "divergence": 0.3,
