957	        // The last few lines each agent streamed are kept, and show under its
958	        // step while it runs.
959	        view.read_with(cx, |view, _| {
960	            assert_eq!(
961	                view.stream(Step::Code),
962	                [2, 3, 4].map(|turn| format!(r#"{{"type":"assistant","turn":{turn}}}"#))
963	            );
964	        });
965	        cx.update_window(handle, |_, window, cx| {
966	            window.render_frame(cx);
967	            assert!(window.try_find(("divergence-stream", 1usize)).is_none());
968	        })
969	        .unwrap();
