989	                view.selected(),
990	                Some("spec/ui/components/scrollbar/index.pi")
991	            );
992	        });
993	        cx.update_window(handle, |_, window, cx| {
994	            window.render_frame(cx);
995	            window.click("divergence-side-source", cx);
996	        })
997	        .unwrap();
998	        cx.run_until_parked();
999	        view.read_with(cx, |view, _| {
1000	            assert_eq!(view.side(), Side::Source);
1001	            assert_eq!(view.selected(), None);
1002	        });
1003	    }
