1005	    /// An agent that fails is marked so, and what the other found still shows.
1006	    #[gpui_kit::test]
1007	    async fn one_failed_agent_still_shows_the_other(cx: &mut TestAppContext) {
1008	        let (view, handle) = open(cx, failing_spec_agent);
