            notes: Vec::new(),
        };
        save_report(&dir, &older).unwrap();
        save_report(&dir, &newer).unwrap();
        // Made in the same second, it is saved beside the other.
        save_report(&dir, &newer).unwrap();
        std::fs::write(dir.join("broken.json"), "{").unwrap();
        let loaded = load_reports(&dir);
        assert_eq!(loaded.len(), 3);
